const TYPE_LABELS = ["Pojem a význam", "Příklad z praxe", "Trenérské rozhodnutí", "Správné spojení"];

function hashString(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function seededShuffle(items, seedText) {
  const array = [...items];
  let seed = hashString(seedText) || 1;
  for (let index = array.length - 1; index > 0; index -= 1) {
    seed ^= seed << 13;
    seed ^= seed >>> 17;
    seed ^= seed << 5;
    const swapIndex = (seed >>> 0) % (index + 1);
    [array[index], array[swapIndex]] = [array[swapIndex], array[index]];
  }
  return array;
}

// One-based concept positions share examples or broader/narrower meanings.
// Keep them apart both from the answer and from each other: variant 4 swaps
// distractor definitions and could otherwise produce another defensible pair.
