const BROAD_DISTRACTORS = {
  regenerace: [1, 26, 27],
};

function distractorIndices(category, index, length, variant) {
  const offsets = [
    [3, 9, 16],
    [5, 12, 19],
    [7, 14, 22],
    [4, 11, 18],
  ][variant];
  const groups = DISTRACTOR_GROUPS[category] ?? [];
  const overlaps = (left, right) => groups.some((group) =>
    group.includes(left + 1) && group.includes(right + 1));
  const preferred = offsets.map((offset) => (index + offset) % length);
  const fallback = Array.from({ length: length - 1 }, (_, offset) =>
    (index + offset + 1) % length);
  const selected = [];
  for (const candidate of [...preferred, ...fallback]) {
    if (candidate === index || selected.includes(candidate)) continue;
    if ((BROAD_DISTRACTORS[category] ?? []).includes(candidate + 1)) continue;
    if ([index, ...selected].some((other) => overlaps(candidate, other))) continue;
    selected.push(candidate);
    if (selected.length === 3) return selected;
  }
  throw new Error(`Nedostatek jednoznačných možností: ${category}/${index + 1}/${variant + 1}`);
}

function makeQuestion(category, concept, index, variant, concepts) {
  const distractors = distractorIndices(category, index, concepts.length, variant).map((itemIndex) => concepts[itemIndex]);
  const code = `${String(CATEGORY_META.find((item) => item.id === category).index).padStart(2, "0")}-${String(index * 4 + variant + 1).padStart(3, "0")}`;
  let prompt;
  let correct;
  let wrong;

  if (variant === 0) {
    prompt = `Co nejlépe vystihuje pojem „${concept.term}“?`;
    correct = concept.definition;
    wrong = distractors.map((item) => item.definition);
  } else if (variant === 1) {
    prompt = `Který pojem popisuje tento příklad? „${concept.example}“`;
    correct = concept.term;
    wrong = distractors.map((item) => item.term);
  } else if (variant === 2) {
    prompt = `Který pojem spojuje tuto situaci a její trenérský význam? „${concept.example} ${concept.importance}“`;
    correct = concept.term;
    wrong = distractors.map((item) => item.term);
  } else {
    prompt = "Které spojení pojmu a vysvětlení je správné?";
    correct = `${concept.term} — ${concept.definition}`;
    wrong = distractors.map((item, distractorIndex) => {
      const shifted = distractors[(distractorIndex + 1) % distractors.length];
      return `${item.term} — ${shifted.definition}`;
    });
  }

  const tagged = [
    { text: correct, correct: true },
    ...wrong.map((text) => ({ text, correct: false })),
  ];
  const options = seededShuffle(tagged, `${category}-${index}-${variant}`);

  return {
    id: code,
    category,
    type: TYPE_LABELS[variant],
    prompt,
    options: options.map((option) => option.text),
    correctIndex: options.findIndex((option) => option.correct),
    explanation: `${concept.definition} ${concept.importance}`,
    sources: concept.sources,
  };
}

export function buildQuestionBank() {
  return Object.entries(CONCEPTS).flatMap(([category, concepts]) =>
    concepts.flatMap((concept, index) =>
      [0, 1, 2, 3].map((variant) => makeQuestion(category, concept, index, variant, concepts)),
    ),
  );
}
